import fs from 'node:fs';import crypto from 'node:crypto';
import {runFlight} from '../src/flight-model.mjs';import {DEFAULTS,CONFIGS,calculate,presentationEvents,statusBits}from'../src/revision51-model.mjs';import {impactEstimate}from'../src/mission-telemetry.mjs';
const review=JSON.parse(fs.readFileSync('data/revision51/requirement_evidence.json')),requirements=JSON.parse(fs.readFileSync('data/revision51/requirements.json'));
const cases={};for(const key of ['A','B']){const inputs={...DEFAULTS,...CONFIGS[key],suspendedKg:CONFIGS[key].wetKg,inertia:key==='A'?1.5:3.75};cases[key]={inputs,flight:runFlight(key,inputs),screen:calculate(inputs)};}
const A=cases.A.flight,B=cases.B.flight,checks={};
const add=(id,title,pass,actual,criterion,limits,implementation)=>checks[id]={id,title,result:pass?'pass':'shortfall',actual,criterion,limits,implementation};
for(const [key,{inputs,flight:f}]of Object.entries(cases))add('S-DELIVERY-'+key,key+' nominal per-vehicle delivery',f.entry.reached&&f.descent.probes.length===inputs.count&&f.descent.probes.every(p=>Math.abs(p.rows.at(-1).alt)<1e-7)&&Math.abs(f.descent.rows.at(-1).alt)<1e-7,{count:f.descent.probes.length,probeMassKg:inputs.probeKg,probeImpactMps:f.descent.probes.map(p=>p.impactV),carrierGroundM:f.descent.rows.at(-1).alt},'Expected probe count; every propagated probe and carrier reaches h=0.','Ground arrival in a point-mass model is not impact survival or successful science. B runs one vehicle; the second identical vehicle is not a coupled simulation.','src/flight-model.mjs: integrateCarrier / integrateProbe');
add('S-ORBIT','300 km orbit to descending 125 km interface',[A,B].every(f=>f.coast.reached&&f.coast.vr<0&&Math.abs(f.burn.rows[0].alt-300000)<1e-5),Object.fromEntries(Object.entries(cases).map(([k,{flight:f}])=>[k,{initialAltitudeM:f.burn.rows[0].alt,interfaceSpeedMps:f.coast.entryV,flightPathDeg:f.coast.flightPathDeg}])),'Both cases start at 300 km and reach the descending entry interface.','Reduced-order deterministic trajectory; no navigation estimation or corridor qualification.','src/flight-model.mjs: integrateBurn / coastToInterface');
add('S-GAS','Paired-jet momentum, slew and storage closure',[A,B].every(f=>Math.abs(f.gas.sepThrust*f.gas.sepSec/cases[f.configuration].inputs.wetKg-.2)<1e-10&&f.gas.reserveKg>0&&Math.abs(f.gas.remainingKg+f.gas.totalManeuverKg+f.gas.leakageKg-f.gas.initialKg)<1e-10&&Math.abs(f.gas.torque/f.options.inertia*(f.gas.heatSlewSec/2)**2-Math.PI)<1e-10&&Math.abs(f.gas.torque/f.options.inertia*(f.gas.slewSec/2)**2-Math.PI/2)<1e-10),Object.fromEntries(Object.entries(cases).map(([k,{flight:f}])=>[k,{separationGasKg:f.gas.sepKg,alignmentGasKg:f.gas.slewKg,heatShieldAlignmentGasKg:f.gas.heatSlewKg,totalManeuverGasKg:f.gas.totalManeuverKg,initialGasKg:f.gas.initialKg,reserveAboveMinimumKg:f.gas.reserveKg,slewSeconds:f.gas.slewSec}])),'Δv_sep=0.2 m/s; scalar 90° retroburn and 180° heat-shield rest-to-rest slew identities; all three gas withdrawals close; positive gas above minimum pressure.','Ideal N2 at 293 K; assumed inertia; no 3-axis control, hardware feed losses, regulator sizing or fault simulation.','src/flight-model.mjs: gasBudget');
add('S-ENGINE','Nominal finite-burn A/B performance',A.burn.idealDv>=A.requiredDv&&Math.abs(B.burn.idealDv-B.requiredDv)<1e-6,{A:{idealDvMps:A.burn.idealDv,requiredDvMps:A.requiredDv,burnSeconds:A.burn.duration},B:{thrustN:B.burn.thrustN,idealDvMps:B.burn.idealDv,requiredDvMps:B.requiredDv,fuelKg:B.BfuelKg,oxidizerKg:B.BoxidizerKg}},'A nominal Δv ≥ vacuum demand; B nominal Δv closes within 10⁻⁶ m/s.','B thrust is sized from the same assumed Isp demand relation, an algebraic closure rather than independent hardware proof. Neither case proves pointing or delivered motor curve.','src/flight-model.mjs: rocketPropellant / integrateBurn / runFlight');
add('S-A-MARGIN','A reference motor versus 25% planning allowance',A.burn.idealDv>=cases.A.screen.designDv,{achievedDvMps:A.burn.idealDv,planningDemandMps:cases.A.screen.designDv,shortfallMps:cases.A.screen.designDv-A.burn.idealDv},'Achieved A Δv ≥ nominal vacuum demand × 1.25.','This check intentionally reports the current baseline shortfall; reaching the atmosphere is not margin compliance.','src/flight-model.mjs: runFlight / src/revision51-model.mjs: calculate');
add('S-TARGET','Nominal target screening within source planning radii',[A,B].every(f=>f.target.best.orbitsElapsed>=3&&f.target.best.orbitsElapsed<=20&&f.target.best.missKm<=CONFIGS[f.configuration].targetRadiusKm),Object.fromEntries(Object.entries(cases).map(([k,{flight:f}])=>[k,{missKm:f.target.best.missKm,planningRadiusKm:CONFIGS[k].targetRadiusKm,orbits:f.target.best.orbitsElapsed}])),'Nominal closest miss within A 100 km / B 50 km; opportunity in 3–20 orbits.','Not a 95% Monte Carlo result. Initial geometry/target assumed; no terrain exclusion.','src/flight-model.mjs: searchGroundTarget');
add('S-ENTRY','Finite entry load trajectory',[A,B].every(f=>f.entry.reached&&f.entry.rows.every(r=>Number.isFinite(r.dynamicPressure)&&Number.isFinite(r.v))),Object.fromEntries(Object.entries(cases).map(([k,{flight:f}])=>[k,{peakDynamicPressurePa:Math.max(...f.entry.rows.map(r=>r.dynamicPressure)),entryDurationSec:f.entry.duration,extractionAltitudeM:f.entry.last.alt}])),'Finite nominal state history reaches assumed 10 km extraction gate.','Zero lift and heat-shield-forward attitude are imposed. No attitude stability, structural strength or safe Mach/q deployment limit is tested.','src/flight-model.mjs: integrateEntry');
add('S-THERMAL','Finite two-location temperature history',[A,B].every(f=>f.entry.rows.every(r=>Number.isFinite(r.centerC)&&Number.isFinite(r.shoulderC))&&f.entry.peakCenterC>f.entry.peakShoulderC),Object.fromEntries(Object.entries(cases).map(([k,{flight:f}])=>[k,{peakCenterC:f.entry.peakCenterC,peakShoulderC:f.entry.peakShoulderC}])),'Finite history; center peak exceeds shoulder peak under chosen flow multiplier.','Numerical sanity only. Assumed nonablating properties; not material qualification or acceptable shell/electronics temperatures.','src/flight-model.mjs: temperatureStep / integrateEntry');
add('S-DESCENT','Independent carrier and probe time histories',[A,B].every(f=>f.descent.probes.every(p=>p.rows.every((r,i)=>Number.isFinite(r.v)&&(!i||r.t>p.rows[i-1].t))&&p.duration>0)),Object.fromEntries(Object.entries(cases).map(([k,{flight:f}])=>[k,{carrierDurationSec:f.descent.duration,canopyCarrierM:CONFIGS[k].pcmChuteM,canopyProbeM:CONFIGS[k].probeChuteM,probeDurationSec:f.descent.probes.map(p=>p.duration)}])),'Finite time-ordered probe trajectories and positive descent duration; default canopy inputs.','Linear inflation proxy and scalar drag, not real deployment opening loads or pendulum/attitude stability.','src/flight-model.mjs: integrateCarrier / integrateProbe');
add('S-RELEASE','Altitude gate, cadence and inherited release state',[A,B].every(f=>f.descent.releases.every((r,i)=>f.descent.probes[i].rows[0].alt===r.state[1]&&(!i||Math.abs(r.t-f.descent.releases[i-1].t-f.options.releaseCadenceSec)<1e-6))&&Math.abs(f.descent.releases[0].state[1]-f.options.releaseAltM)<1e-4&&Math.abs(f.descent.initialMass-f.descent.finalMass-cases[f.configuration].inputs.count*2)<1e-8),Object.fromEntries(Object.entries(cases).map(([k,{flight:f}])=>[k,{firstAltitudeM:f.descent.releases[0].state[1],releaseTimesSec:f.descent.releases.map(r=>r.t),initialMassKg:f.descent.initialMass,finalMassKg:f.descent.finalMass}])),'Sequential release, inherited altitude and released probe mass closure.','Point bodies do not test mechanical interference, separation clearances or actuator reliability.','src/flight-model.mjs: integrateCarrier / integrateProbe');
const windy=runFlight('A',cases.A.inputs,{windMps:20,rho0:.012});
add('S-ATMOSPHERE','Density / wind sensitivity',windy.entry.reached&&Math.abs(windy.descent.probes[0].impactV-A.descent.probes[0].impactV)>.01,{baselineWindMps:0,tradeWindMps:20,baselineRho0:.015,tradeRho0:.012,baselineImpactMps:A.descent.probes[0].impactV,tradeImpactMps:windy.descent.probes[0].impactV},'A changed atmosphere/wind case reaches extraction and changes impact speed.','One combined sensitivity case, not separate attribution, site elevation modeling or a probabilistic atmosphere ensemble.','src/flight-model.mjs: integrateEntry / lowAltitudeDerivative');
add('S-LINK','Assumed RF link and duty-cycle screen',Object.values(cases).every(c=>c.screen.linkMargin>0),{linkMarginDb:cases.A.screen.linkMargin,frequencyMHz:400,rangeKm:400,rfW:10,receiverDbm:-120,transmitWhPerHour:cases.A.screen.txWhHour},'Free-space link margin > 0 dB at the default assumed geometry/receiver.','Not an actual radio, pulse buffer, relay contract, contact schedule, outage/blackout or data-retention test.','src/revision51-model.mjs: calculate');
add('S-POWER','Surface energy screening with 20% reserve',Object.values(cases).every(c=>c.screen.energyRemaining>=.2*c.inputs.energyWh),Object.fromEntries(Object.entries(cases).map(([k,c])=>[k,{usableWh:c.inputs.energyWh,loadWh:c.screen.scienceEnergy,residualWh:c.screen.energyRemaining,requiredReserveWh:.2*c.inputs.energyWh,operationHours:c.inputs.operationHours}])),'Usable energy − average load × duration ≥ 20% of usable energy.','Assumed already-usable capacity and average load; no environmental derating, heater/peak-current waveform or selected battery.','src/revision51-model.mjs: calculate');
add('S-STATUS','Cumulative payload identities',[3,7].every(n=>{const e=presentationEvents(n),b=statusBits(e,e.length,n);return b.length===(n===3?9:13)&&b.every(x=>x===1)&&e.find(x=>x.id==='carrier-landing').bit===8;}),{A_bits:9,B_bits:13,carrierLandingBit:8},'All bits latch at completion, with stable bit identity in A and B.','Synthetic review markers; not actual sensors, flight 60 s timer, RF reception, nonvolatile reset recovery or science packets.','src/revision51-model.mjs: statusBits / presentationEvents');
const v=85,m=2,area=Math.PI*.05**2/4,constant=impactEstimate(v,m,'sand',{sandCd:0});
add('S-IMPACT','Impact-screen analytical identity',Math.abs(constant.depth-m*v*v/(2*area*.2e6))<1e-9,{testVelocityMps:v,massKg:m,constantResistanceDepthM:constant.depth,softSandScreenAt85Mps:impactEstimate(v,m,'sand').depth},'Zero inertial-coefficient limit reproduces constant-force work/energy penetration.','Uncalibrated material assumptions, no fracture/crush/instrument shock. Mathematical identity is not soil penetration or survival validation.','src/mission-telemetry.mjs: impactEstimate');
add('S-TRACE','Complete source identifier preservation',requirements.length===91&&new Set(requirements.map(r=>r.id)).size===91,{sourceRequirementCount:requirements.length,evidenceAssessmentCount:review.requirements.length},'91 distinct source IDs and matching evidence records.','Does not establish approved acceptance criteria, named owners or full objective/design/anomaly traceability.','data/revision51/requirements.json');
const sha=file=>crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex');
review.checks=checks;review.provenance={sourceCommit:null,modelSha256:Object.fromEntries(['src/flight-model.mjs','src/revision51-model.mjs','src/mission-telemetry.mjs','data/revision51/requirements.json'].map(f=>[f,sha(f)])),generator:'scripts/build-requirement-evidence.mjs',reproduce:'node scripts/build-requirement-evidence.mjs',testLog:'data/revision51/evidence/test-results.txt',note:'Checks use fresh baseline runs. Review is a fixed baseline assessment; changing website sliders does not alter these evidence marks.'};
review.counts={total:91,simulationSupport:review.requirements.filter(r=>['partial','supported'].includes(r.simulation.status)).length,simulationShortfall:review.requirements.filter(r=>r.simulation.status==='shortfall').length,flightHeritage:review.requirements.filter(r=>r.heritage.status==='partial').length,negativeHeritage:review.requirements.filter(r=>r.heritage.status==='negative').length,fullyVerified:0};
fs.writeFileSync('data/revision51/requirement_evidence.json',JSON.stringify(review,null,2)+'\n');fs.writeFileSync('src/requirement-evidence.mjs','// Generated by scripts/build-requirement-evidence.mjs\nexport const EVIDENCE_REVIEW='+JSON.stringify(review,null,2)+';\n');
fs.writeFileSync('data/revision51/evidence/baseline_inputs.json',JSON.stringify(Object.fromEntries(Object.entries(cases).map(([k,c])=>[k,{inputs:c.inputs,options:c.flight.options}])),null,2)+'\n');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={supported:'Simulation: numerical support',partial:'Simulation: partial support',shortfall:'Simulation: shortfall',none:'Simulation: not demonstrated'};
const links=r=>r.simulation.checks.map(id=>`<a href="#${id}">${id}</a>`).join(' · '),heritage=r=>r.heritage.sources.map(id=>`<a href="#${id}">${id}</a>`).join(' · ')||'No applicable demonstrated flight evidence identified in this review';
const rows=review.requirements.map(r=>{const source=requirements.find(x=>x.id===r.id);return `<article id="${r.id}"><h2>${r.id} · ${esc(source.applies)}</h2><p>${esc(source.text)}</p><p><strong>${labels[r.simulation.status]}</strong></p><p>${esc(r.simulation.scope)} ${links(r)}</p><p><strong>${r.heritage.status==='partial'?'Flight-demonstrated analogous element':r.heritage.status==='negative'?'Caution: mission not successful':'Flight evidence not established'}</strong> · ${heritage(r)}</p><p><strong>Remaining FREYA verification:</strong> ${esc(r.remaining)}</p><small>Original verification statement: ${esc(source.verification)}. FREYA requirement remains open.</small></article>`;}).join('');
const checksHtml=Object.values(checks).map(c=>`<article id="${c.id}"><h2>${c.id} · ${esc(c.title)}</h2><p><strong>${c.result==='pass'?'PASS of stated numerical subcheck':'BASELINE SHORTFALL'}</strong></p><p>Criterion: ${esc(c.criterion)}</p><pre>${esc(JSON.stringify(c.actual,null,2))}</pre><p>Limits: ${esc(c.limits)}</p><p>Implementation: ${esc(c.implementation)}</p></article>`).join('');
const sourceHtml=Object.entries(review.sources).map(([id,s])=>`<article id="${id}"><h2>${id}</h2><p>${esc(s.citation)}</p><p><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.url)}</a></p><p>Accessed ${s.accessed}. Demonstrated scope: ${esc(s.demonstrated)}</p></article>`).join('');
fs.writeFileSync('requirement-evidence.html',`<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FREYA · 91 requirement evidence register</title><link rel="stylesheet" href="src/revision51.css"><style>main{max-width:1100px}article{padding:22px;margin:18px 0;border:1px solid #35536a;border-radius:12px;background:#112338}article:target{outline:2px solid #72dfca}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#071522;padding:14px}h1{font-size:2rem}</style><header><a href="index.html#requirements">← Requirements panel</a><h1>FREYA Rev09 · requirement evidence register</h1><p>Review ${review.reviewDate} · Revision 5.1 default baselines. ${esc(review.meaning)}</p><p>${review.counts.simulationSupport} with simulation support; ${review.counts.flightHeritage} with analogous flight heritage; ${review.counts.simulationShortfall} with a simulation shortfall. Categories overlap. 0 fully verified FREYA requirements.</p><nav><a href="#assessments">91 assessments</a><a href="#simulation-checks">Reproducible simulation results</a><a href="#references">Full references</a><a href="data/revision51/requirement_evidence.json" download>Download JSON</a><a href="data/revision51/evidence/requirements_evidence.csv" download>Download CSV</a><a href="data/revision51/evidence/test-results.txt">Regression test log</a><a href="data/revision51/evidence/build-requirement-evidence.mjs">Check generator source</a></nav></header><main><p class="notice">Inputs, drawings, animations, assumed stable attitude and positive algebraic balances are not hardware qualification. Heritage applies only to the cited demonstrated element and its original mission. No FREYA compliance is inherited automatically. Deep Space 2 is explicitly excluded as successful penetrator heritage. The separate Aeolus reference is not used.</p><h1 id="assessments">91 individual assessments</h1>${rows}<h1 id="simulation-checks">Simulation evidence</h1><p>Fresh baseline runs; all values use SI units unless labeled. Model source hashes identify this recomputed baseline; original assessment commit ${review.assessedSourceCommit}. <a href="data/revision51/evidence/baseline_inputs.json">Complete inputs/options</a>. <a href="data/revision51/requirement_evidence.json">Model SHA-256 fingerprints, criteria and complete provenance</a>.</p>${checksHtml}<h1 id="references">Full primary-source references</h1>${sourceHtml}</main></html>`);
const csv=[['Requirement','Applies','Requirement text','Simulation evidence','Simulation scope','Simulation check references','Flight heritage','Primary evidence URLs','Remaining FREYA verification','Fully verified']];for(const r of review.requirements){const q=requirements.find(x=>x.id===r.id);csv.push([r.id,q.applies,q.text,r.simulation.status,r.simulation.scope,r.simulation.checks.join(' '),r.heritage.status,r.heritage.sources.map(id=>review.sources[id].url).join(' '),r.remaining,'No']);}fs.writeFileSync('data/revision51/evidence/requirements_evidence.csv',csv.map(row=>row.map(x=>'"'+String(x).replaceAll('"','""')+'"').join(',')).join('\r\n')+'\r\n');
fs.copyFileSync('scripts/build-requirement-evidence.mjs','data/revision51/evidence/build-requirement-evidence.mjs');
console.log(JSON.stringify({counts:review.counts,checks:Object.values(checks).length,expectedShortfalls:Object.values(checks).filter(c=>c.result!=='pass').map(c=>c.id)},null,2));
